const pairs = $('Build Tavily Pairs').all().map(i => i.json);
function extractResults(j) {
  let obj = j;
  if (typeof obj === 'string') { try { obj = JSON.parse(obj); } catch (e) { return []; } }
  if (!obj || typeof obj !== 'object') return [];
  if (obj.structuredContent && Array.isArray(obj.structuredContent.results)) return obj.structuredContent.results;
  if (Array.isArray(obj.results)) return obj.results;
  if (typeof obj.result === 'string') { try { const p = JSON.parse(obj.result); return p.results || []; } catch (e) { return []; } }
  if (Array.isArray(obj.content)) {
    for (const c of obj.content) { if (c && typeof c.text === 'string') { try { const p = JSON.parse(c.text); if (p.results) return p.results; } catch (e) {} } }
  }
  return [];
}
function clean(x) {
  return String(x == null ? '' : x).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])/g, '').replace(/(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g, '');
}
function cutSafe(s, n) { const t = String(s).slice(0, n); return t.replace(/[\uD800-\uDBFF]$/, ''); }
function domainOf(u) {
  let d = String(u || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '');
  return d.split('/')[0].split('?')[0];
}
function pathOf(u) {
  const str = String(u || '').replace(/^https?:\/\/[^/]+/i, '');
  return str || '/';
}
const SKIP = ['tripadvisor.', 'yelp.', 'zomato.', 'foursquare.', 'yellowpages.', 'hotfrog.', 'trustpilot.', 'reddit.com', 'cbinsights.com', 'rocketreach.co', 'crunchbase.com', 'linkedin.com', 'wanderlog.com', 'quora.com', 'medium.com'];
const out = [];
const seen = {};
const allLocToks = {};
for (const pp of pairs) { for (const w of String(pp.location || '').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean)) allLocToks[w] = 1; }
const profToks = {};
for (const pp of pairs) { for (const w of String(pp.query || '').toLowerCase().split(/[^a-z0-9]+/)) { if (w.length > 2 && !allLocToks[w] && ['best', 'top', 'near', 'with', 'from', 'that', 'this'].indexOf(w) === -1) profToks[w.replace(/s$/, '')] = 1; } }
const RESERVED_FB = { groups: 1, events: 1, marketplace: 1, watch: 1, people: 1, search: 1, sharer: 1, share: 1, login: 1, help: 1, pages: 1, gaming: 1, stories: 1, reels: 1, 'home.php': 1, 'l.php': 1 };
function fbAccount(u) {
  if (/profile\.php/i.test(u)) { const pr = u.match(/[?&]id=(\d+)/); return pr ? { url: 'https://www.facebook.com/profile.php?id=' + pr[1], personal_risk: true } : null; }
  const m = String(u).match(/^https?:\/\/(?:www\.|m\.)?facebook\.com\/(.+)$/i);
  if (!m) return null;
  const parts = m[1].split('?')[0].replace(/\/+$/, '').split('/').filter(Boolean);
  if (!parts.length) return null;
  const first = parts[0];
  if (RESERVED_FB[first.toLowerCase()]) return null;
  if (first === 'p' && parts.length >= 2) return { url: 'https://www.facebook.com/p/' + parts[1], personal_risk: false, collapsed: true };
  if (/^\d{6,}$/.test(first)) return { url: 'https://www.facebook.com/' + first, personal_risk: false, collapsed: parts.length > 1 };
  if (/^[A-Za-z0-9.\-_]+$/.test(first)) return { url: 'https://www.facebook.com/' + first, personal_risk: false, collapsed: parts.length > 1 };
  return null;
}
function ttAccount(u) {
  const m = String(u).match(/^https?:\/\/www\.tiktok\.com\/@([A-Za-z0-9._\-]+)/i);
  return m ? { url: 'https://www.tiktok.com/@' + m[1].toLowerCase(), handle: m[1].toLowerCase(), personal_risk: false } : null;
}
function socialName(platform, acc, titleRaw) {
  let name = titleRaw;
  if (name.includes(' | ')) name = name.split(' | ')[0].trim();
  name = name.replace(/\s*[-\u2013\u2014]\s*(Home|Facebook|Instagram|TikTok)\s*$/i, '').trim();
  if (platform === 'tiktok') {
    const mm = titleRaw.match(/^(.+?)\s*\(@[A-Za-z0-9._\-]+\)/);
    if (mm) name = mm[1].trim();
    else if (/^(tiktok|log in|make your day)/i.test(name) || name.length < 2) name = acc.handle || name;
  }
  if (name.length > 120) name = name.slice(0, 120);
  return name;
}
const socialAcc = {};
$input.all().forEach((item, idx) => {
  const pair = pairs[idx] || {};
  const locToks = String(pair.location || '').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  const qToks = String(pair.query || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 2 && locToks.indexOf(w) === -1 && ['best', 'top', 'near', 'with', 'from', 'that', 'this'].indexOf(w) === -1);
  for (const r of extractResults(item.json)) {
    const url = clean((r && r.url) || '').trim();
    const titleRaw = clean((r && r.title) || '').trim();
    if (!url || !titleRaw) continue;
    if (/\b(top|best)\s+\d+\b/i.test(titleRaw)) continue;
    if (/\b(best|top)\b/i.test(titleRaw)) {
      const tw = titleRaw.toLowerCase().split(/[^a-z0-9]+/).map(w => w.replace(/s$/, ''));
      if (tw.some(w => profToks[w])) continue;
    }
    if (pair.social_platform) {
      const acc = pair.social_platform === 'facebook' ? fbAccount(url) : ttAccount(url);
      if (!acc) continue;
      if (!socialAcc[acc.url]) {
        socialAcc[acc.url] = { json: {
          source: 'tavily_social', source_id: acc.url, name: socialName(pair.social_platform, acc, titleRaw), place_id: null,
          category: pair.category || null, location: pair.location || null,
          website: null, domain: null, phone: null, rating: null, review_count: null,
          source_url: acc.url,
          raw: { social_platform: pair.social_platform, social_url: acc.url, result_urls: [], name_provisional: pair.social_platform === 'tiktok' || !!acc.collapsed, personal_risk: !!acc.personal_risk, title: titleRaw, snippet: cutSafe(clean((r && r.content) || ''), 300), query: pair.query || '' }
        } };
        out.push(socialAcc[acc.url]);
      }
      socialAcc[acc.url].json.raw.result_urls.push(url);
      continue;
    }
    const dom = domainOf(url);
    if (!dom) continue;
    if (SKIP.some(x => dom.includes(x))) continue;
    const path = pathOf(url);
    if (path.includes('/search') || path.includes('/groups/') || path.includes('/watch')) continue;
    const segs = path.split('/').filter(Boolean);
    if ((dom === 'facebook.com' || dom === 'instagram.com') && segs.length !== 1) continue;
    const seg = segs[0] || '';
    const key = (dom === 'facebook.com' || dom === 'instagram.com') ? dom + '|' + seg.toLowerCase() : dom;
    if (seen[key]) continue;
    seen[key] = 1;
    let name = titleRaw;
    if (name.includes(' | ')) name = name.split(' | ')[0].trim();
    name = name.replace(/\s*[-–—]\s*(Home|Facebook|Instagram)\s*$/i, '').trim();
    if (!name || name.length < 2) continue;
    if (name.length > 120) name = name.slice(0, 120);
    out.push({ json: {
      source: 'tavily_web', source_id: null, name: name, place_id: null,
      category: pair.category || null, location: pair.location || null,
      website: url, domain: dom, phone: null, rating: null, review_count: null,
      source_url: url,
      raw: { title: titleRaw, url: url, snippet: cutSafe(clean((r && r.content) || ''), 300), score: (r && r.score) || null, query: pair.query || '' }
    } });
  }
});
return out;

